    // One WeakMap-backed toString. Anything we install registers its fake source here, so
    // Function.prototype.toString is the only patched function on the page and it answers
    // truthfully for everything we did not touch.
    const SOURCES = new WeakMap();
    const nativeToString = Function.prototype.toString;
    // Held before anything is patched. The window key list is overridden further down, so
    // any later use of Object.getOwnPropertyNames(G) would enumerate the *device* list and
    // walk straight past the real globals it is supposed to be removing.
    const nativeOwnNames = Object.getOwnPropertyNames;

    const cloak = (fn, source) => { SOURCES.set(fn, source); return fn; };
    const asNative = (fn, name) => cloak(fn, 'function ' + name + '() {\n    [native code]\n}');
    // JSC names an accessor 'get userAgent' but reports its source as 'function userAgent()' --
    // the two disagree, and the capture is the authority. Measured, not assumed.
    const asGetter = (fn, name) => cloak(fn, 'function ' + name + '() {\n    [native code]\n}');

