    // hsw's per-property probe records `"prototype" in fn` over 35 [ctor, prop] pairs -- among them
    // Navigator.userAgent, Screen.width, HTMLCanvasElement.toDataURL and WebGLRenderingContext
    // .getParameter. That probe is gated on `83 === <engine>`, which our persona is not, so it runs.
    // Method and accessor shorthand build functions with dynamic `this` and no .prototype.
    // The object literal's property is `m`, so what comes back is named 'm' / 'get m' / 'set m'
    // unless the caller renames it -- and five install sites did not, which left five unrelated
    // interfaces all reporting the SAME made-up name. That is worse than an anonymous function: it
    // is a signature. The rename moves INSIDE the helpers so it cannot be forgotten again. The name
    // is passed in because the helper cannot know it, and a caller that omits it gets '' -- a
    // generic "patched" tell rather than one unique to this script.
    const renamed = (fn, name) => {
        try { Object.defineProperty(fn, 'name', { value: name || '', configurable: true }); } catch (e) { }
        return fn;
    };
    const noProtoMethod = (impl, name) => renamed(({ m() { return impl.apply(this, arguments); } }).m, name);
    const noProtoGetter = (impl, name) => renamed(Object.getOwnPropertyDescriptor({ get m() { return impl.call(this); } }, 'm').get, name ? 'get ' + name : '');
    // A getter shorthand takes no argument, so it cannot stand in for a setter: the value never
    // arrives. Setters get their own shorthand, which also gives them the native length of 1.
    const noProtoSetter = (impl, name) => renamed(Object.getOwnPropertyDescriptor({ set m(v) { impl.call(this, v); } }, 'm').set, name ? 'set ' + name : '');

