    // function on the page, not just the ones we install, so the cloak reformats what it passes
    // through rather than only answering for its own entries.
    const V8_NATIVE = /^(function [^(]*\(\)|class [^ ]*) \{ \[native code\] \}$/;

    // V8 also writes an accessor's ROLE into its source -- `function get navigation() { [native code] }`
    // -- where JSC prints the bare property name. The capture records exactly that pair for the
    // device (engine.accessorName: name 'get userAgent', src 'function userAgent() {...}') and
    // asGetter above already follows it for everything this script installs. Every NATIVE accessor
    // it did not touch still came back V8-shaped, so one page answered both ways at once:
    // `function pushManager()` beside `function get localStorage()`. hsw reads precisely these -- it
    // sweeps the tail of the window name list with getOwnPropertyDescriptor and calls toString on
    // each getter (38 reads per solve on build 52b3815e). A function genuinely NAMED get or set
    // (Map.prototype.get) has no second word, so the lookahead leaves it alone.
    const V8_ACCESSOR = /^function (?:get|set) (?=[^\s(])/;

