        Wrapped.prototype = Original.prototype;
        Object.getOwnPropertyNames(Original).forEach((key) => {
            if (key === 'prototype' || key === 'name' || key === 'length') return;
            try { Wrapped[key] = Original[key]; } catch (e) { }
        });
        Object.defineProperty(Wrapped, 'name', { value: name, configurable: true });
        Object.defineProperty(Wrapped, 'length', { value: Original.length, configurable: true });
        asNative(Wrapped, name);
        try { Object.defineProperty(Original.prototype, 'constructor', { value: Wrapped, writable: true, configurable: true }); } catch (e) { }
